# ---- Client ----


class FlowplanError(Exception):
    """An answer with a status outside 2xx; `message` is the server's text in the reader's language."""

    def __init__(self, status: int, message: str, details: Optional[list[str]] = None, retry_after: Optional[int] = None):
        super().__init__(f"{status}: {message}")
        self.status = status
        self.message = message
        self.details = details or []
        self.retry_after = retry_after


def _p(value: Any) -> str:
    return quote(str(value), safe="")


def _pause(attempt: int, retry_after: Optional[int]) -> None:
    _time.sleep(min(retry_after, 30) if retry_after else 0.5 * 2**attempt)


class FlowplanClient:
    """Calls a Flowplan instance with a personal API token (fp_…)."""

    def __init__(self, base_url: str, token: Optional[str] = None, timeout: float = 60.0, headers: Optional[dict[str, str]] = None, retries: int = 2):
        """`retries`: GET requests and changes with an Idempotency-Key are retried after a network error,
        429, 502, 503, 504 or 409 while the first attempt still runs – changes with the same key, so they
        are applied once."""
        self.base_url = base_url.rstrip("/")
        self.token = token
        self.timeout = timeout
        self.headers = dict(headers or {})
        self.retries = retries

    def request(
        self,
        method: str,
        path: str,
        query: Optional[dict[str, Any]] = None,
        json_body: Any = None,
        form: Optional[dict[str, Any]] = None,
        raw: Optional[bytes] = None,
        content_type: Optional[str] = None,
        headers: Optional[dict[str, str]] = None,
        idempotent: bool = False,
        idempotency_key: Optional[str] = None,
        retries: Optional[int] = None,
    ) -> tuple[int, dict[str, str], bytes]:
        """Any request: status, headers and body. Raises FlowplanError outside 2xx.

        Operations that take an Idempotency-Key get a new one per call (or `idempotency_key`),
        kept on every retry of that call."""
        url = self.base_url + path
        params = {k: v for k, v in (query or {}).items() if v is not None}
        if params:
            url += "?" + urlencode({k: str(v).lower() if isinstance(v, bool) else v for k, v in params.items()})
        send = dict(self.headers)
        send.update(headers or {})
        if self.token:
            send["Authorization"] = f"Bearer {self.token}"
        send.setdefault("Accept", "application/json, */*;q=0.8")
        data: Optional[bytes] = None
        if json_body is not None:
            send["Content-Type"] = "application/json"
            data = _json.dumps(json_body).encode("utf-8")
        elif form is not None:
            boundary = _uuid.uuid4().hex
            send["Content-Type"] = f"multipart/form-data; boundary={boundary}"
            data = _multipart(form, boundary)
        elif raw is not None:
            if content_type:
                send["Content-Type"] = content_type
            data = raw
        key = idempotency_key or (str(_uuid.uuid4()) if idempotent else None)
        if key:
            send["Idempotency-Key"] = key
        attempts = (self.retries if retries is None else retries) if method == "GET" or key else 0
        attempt = 0
        while True:
            try:
                with urlopen(Request(url, data=data, method=method, headers=send), timeout=self.timeout) as response:
                    return response.status, dict(response.headers.items()), response.read()
            except HTTPError as error:
                body = error.read()
                message = f"{error.code} {error.reason}".strip()
                details: Optional[list[str]] = None
                code: Optional[str] = None
                try:
                    parsed = _json.loads(body.decode("utf-8"))
                    message = parsed.get("error") or message
                    details = parsed.get("details")
                    code = parsed.get("code")
                except Exception:
                    pass
                retry = error.headers.get("Retry-After")
                wait = int(retry) if retry and retry.isdigit() else None
                if attempt < attempts and (error.code in (429, 502, 503, 504) or (error.code == 409 and code == "idempotency_in_progress")):
                    _pause(attempt, wait)
                    attempt += 1
                    continue
                raise FlowplanError(error.code, message, details, wait) from None
            except URLError:
                if attempt >= attempts:
                    raise
                _pause(attempt, None)
                attempt += 1

    def _json(self, method: str, path: str, **kwargs: Any) -> Any:
        _, _, body = self.request(method, path, **kwargs)
        return _json.loads(body.decode("utf-8")) if body else None

    def _bytes(self, method: str, path: str, **kwargs: Any) -> bytes:
        return self.request(method, path, **kwargs)[2]

    def health(self, headers: Optional[dict[str, str]] = None) -> "Health":
        """Liveness and readiness — No authentication: answers only `service` and `status` (200, or 503 when the database or the storage fails). The details (`checks`, backlogs, object storage, uptime) come with `FLOWPLAN_METRICS_TOKEN` as bearer token or for a signed-in instance administrator. (GET /api/health)"""
        return self._json("GET", "/api/health", headers=headers)

    def site_info(self, headers: Optional[dict[str, str]] = None) -> "SiteInfo":
        """Whether sign-up, the demo and SSO are open (GET /api/site-info)"""
        return self._json("GET", "/api/site-info", headers=headers)

    def openapi(self, headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """This document — Signed-in people and API tokens; public (`info.version` with the major version only for visitors) when the instance sets `FLOWPLAN_PUBLIC_API_DOCS=true`. (GET /api/openapi.json)"""
        return self._json("GET", "/api/openapi.json", headers=headers)

    def metrics(self, headers: Optional[dict[str, str]] = None) -> bytes:
        """Prometheus metrics — Only with `FLOWPLAN_METRICS_TOKEN` set, sent as bearer token. 404 when metrics are off. (GET /api/metrics)"""
        return self._bytes("GET", "/api/metrics", headers=headers)

    def bootstrap(self, query: Optional["BootstrapQuery"] = None, headers: Optional[dict[str, str]] = None) -> "Bootstrap":
        """Workspaces, spaces, pages and members — Without `workspace` the first workspace. Start here to find IDs. (GET /api/bootstrap)"""
        return self._json("GET", "/api/bootstrap", query=dict(query) if query else None, headers=headers)

    def search(self, query: "SearchQuery", headers: Optional[dict[str, str]] = None) -> list["SearchResult"]:
        """Full-text search — Pages, records, comments and file contents of a workspace. In `q`, `#tag` (or `#"two words"`) keeps pages with that tag, `-#tag` leaves them out, and `name:value` compares a page property (text contains; select and multiselect equal an option; numbers and dates also `>`, `<`, `>=`, `<=`, `a..b`; checkboxes yes/no; people by name or `me`; `name:*` set, `name:-` empty). Tokens that name no tag or property are searched as words; with only tokens, the matching pages are listed by last change. Also `OR` (or `|`), `AND` (implicit), `NOT` or `-` before any term or group, parentheses (NOT binds tightest, then AND, then OR), `created_by:`/`creator:` and `updated_by:`/`editor:` (a name or `me`), `created:` and `updated:` (`2026-03`, `>2026-01-01`, `a..b`, `-7d`, `-2w`, `-3m`, `-1y`, `today`, `yesterday`, `this-week`, `last-week`, `this-month`, `last-month`, `this-year`, `last-year`), `type:document|database|whiteboard|record`, `in:"Space name"` and `title:`; such queries list the matching pages and records (without snippets) by last change. Answered with `Cache-Control: no-store`. (GET /api/search)"""
        return self._json("GET", "/api/search", query=dict(query) if query else None, headers=headers)

    def search_recent(self, query: "SearchRecentQuery", headers: Optional[dict[str, str]] = None) -> list["RecentVisit"]:
        """Your recently visited pages and records — The pages and records you opened last in the workspace, newest first – what the quick search shows with nothing typed. Only your own visits (never other people's), only what you may still read; visits through API tokens are not recorded. Answered with `Cache-Control: no-store`. (GET /api/search/recent)"""
        return self._json("GET", "/api/search/recent", query=dict(query) if query else None, headers=headers)

    def notifications(self, query: Optional["NotificationsQuery"] = None, headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """My newest notifications — What the inbox shows, in short: the line in the reader's language (`Accept-Language` or the language cookie), the record title as `detail`, where it leads and whether push is switched on for its kind (`push`, false for a page that is gone or no longer readable). Without `since` the latest 20; with `since` (server time, e.g. a previous `createdAt`) up to 50 from that second on, newest first. `unread` counts every unread notification. The desktop app polls this instead of Web Push. Marked read with `notification.mark` or `notification.read` via POST /api/command. (GET /api/notifications)"""
        return self._json("GET", "/api/notifications", query=dict(query) if query else None, headers=headers)

    def tasks(self, query: "TasksQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """My tasks — Tasks in documents assigned to you, your own dated ones, those of your journals and of your own task page (`tasks`, command `task.add`), and yours in your other workspaces (`others`). `own` marks tasks of your own task page, `fresh` tasks given to you by others since you last opened My tasks (command `tasks.seen`). `personal` says which page is your own task page (null until the first task) and whether you may add tasks here. (GET /api/tasks)"""
        return self._json("GET", "/api/tasks", query=dict(query) if query else None, headers=headers)

    def records(self, query: "RecordsQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Records across all databases — With an optional filter (JSON, same shape as a view filter group) and the saved record views. (GET /api/records)"""
        return self._json("GET", "/api/records", query=dict(query) if query else None, headers=headers)

    def export_workspace(self, query: "ExportWorkspaceQuery", headers: Optional[dict[str, str]] = None) -> "WorkspaceExport":
        """Whole workspace as JSON — Every readable page outside the trash with its content; records only as far as you may see them. (GET /api/export)"""
        return self._json("GET", "/api/export", query=dict(query) if query else None, headers=headers)

    def offline_changes(self, query: "OfflineChangesQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """What changed for an offline copy — Every page you may read now (outside the trash, no journal behind a PIN) and, since `since`, the pages and visible records whose content changed. Without `since` (or one older than the change log) `full` is true and every page counts as changed. Pass `now` as the next `since`. (GET /api/offline/changes)"""
        return self._json("GET", "/api/offline/changes", query=dict(query) if query else None, headers=headers)

    def offline_assets(self, headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """The app's files for an offline copy — Every file of the running client build under `/_next/static` (scripts, styles, fonts, workers) with its size, followed by the fonts (`/fonts.css`, `/fonts/*.woff2`) and icons the app's page loads from `public`, the build id and the version. A device that keeps an offline copy stores them in a cache named after the build, so parts of the app never opened online load offline as well – also in the iPhone and iPad app, which has no service worker to catch the fonts as they load. (GET /api/offline/assets)"""
        return self._json("GET", "/api/offline/assets", headers=headers)

    def graph(self, query: "GraphQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Links between pages as a graph (GET /api/graph)"""
        return self._json("GET", "/api/graph", query=dict(query) if query else None, headers=headers)

    def tags(self, query: "TagsQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Tags and page properties of a workspace — The tags (`id`, `name`, `color`, `position`, `spaceId` – null for the whole workspace, else the space it belongs to –, `pages`: how many readable pages carry it, `records`: how many readable database records carry it in a property with the tags as options) and the property definitions (`id`, `name`, `type`, `options`, `spaceId`). A space's own tags and properties are listed for those who may open that space (or see a page carrying them) and for workspace owners. Guests see only the tags and properties of pages and records shared with them. A page's own tags and values come with GET /api/pages/{id} as `properties` (`tags`: tag IDs, `values`: by property ID, `info`: created and changed at and by). Answered with `Cache-Control: no-store`. (GET /api/tags)"""
        return self._json("GET", "/api/tags", query=dict(query) if query else None, headers=headers)

    def collections(self, query: "CollectionsQuery", headers: Optional[dict[str, str]] = None) -> list[dict[str, Any]]:
        """Collections of a workspace — The person's own collections and those shared with the workspace (not for guests), in their order: `id`, `name`, `icon`, `query`, `shared`, `mine`, `canEdit`, `ownerName`. Change them with the command actions collection.*. Answered with `Cache-Control: no-store`. (GET /api/collections)"""
        return self._json("GET", "/api/collections", query=dict(query) if query else None, headers=headers)

    def run_collection(self, id: str, query: Optional["RunCollectionQuery"] = None, headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Run a collection — The collection and its current results: `items` (pages and database records with `pageId`, `rowId`, `type`, `title`, `icon`, `spaceId`, `database`, `tags`, `createdAt`, `updatedAt`, `createdBy`, `creatorName`; latest change first, ties by ID), `total` (all matches the reader may read), `offset`, `truncated` (more follow), `nextOffset` (the `offset` of the next page, null on the last) and `encryptedLeftOut` (end-to-end encrypted spaces the reader may read are not searched). Paged: `limit` results (default 500) from `offset` on; the order is stable, so following `nextOffset` reaches every match once while nothing changes. Results follow the reader's own permissions, also for collections shared by others; `total` and the pages count only those. Answered with `Cache-Control: no-store`. (GET /api/collections/{id})"""
        return self._json("GET", "/api/collections/" + _p(id), query=dict(query) if query else None, headers=headers)

    def preview_collection(self, query: "PreviewCollectionQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Results of a query — Like GET /api/collections/{id} for a query that is not saved: `query` (its canonical form) and the first 50 results. Answered with `Cache-Control: no-store`. (GET /api/collections/preview)"""
        return self._json("GET", "/api/collections/preview", query=dict(query) if query else None, headers=headers)

    def tag_pages(self, id: str, query: "TagPagesQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Pages and records with a tag — Like /api/tags, plus `pages`: the readable pages with this tag, and `records`: the readable database records carrying it in a property with the tags as options, latest change first. A tag is one id; with `sameName=1` also the tags of the same name in other spaces. Answered with `Cache-Control: no-store`. (GET /api/tags/{id})"""
        return self._json("GET", "/api/tags/" + _p(id), query=dict(query) if query else None, headers=headers)

    def related(self, query: Optional["RelatedQuery"] = None, headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Related pages, or pages with a similar title — With `page` (and `row`): related pages and records (`items` with their `reasons`) – by meaning when semantic search is on for you, else by links, backlinks, shared links, tags and title. With `workspace` and `title`: existing pages, or records of `database`, with a similar title (duplicate hint). Only what you may read. Answered with `Cache-Control: no-store`. (GET /api/related)"""
        return self._json("GET", "/api/related", query=dict(query) if query else None, headers=headers)

    def templates(self, query: "TemplatesQuery", headers: Optional[dict[str, str]] = None) -> list[dict[str, Any]]:
        """Saved page templates of a workspace (GET /api/templates)"""
        return self._json("GET", "/api/templates", query=dict(query) if query else None, headers=headers)

    def media(self, query: "MediaQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Media library — Files of the pages you may read, 60 per call. (GET /api/media)"""
        return self._json("GET", "/api/media", query=dict(query) if query else None, headers=headers)

    def citations(self, query: "CitationsQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Bibliography of a workspace (GET /api/citations)"""
        return self._json("GET", "/api/citations", query=dict(query) if query else None, headers=headers)

    def capture_targets(self, query: "CaptureTargetsQuery", headers: Optional[dict[str, str]] = None) -> dict[str, Any]:
        """Databases to capture into, and your default (GET /api/capture)"""
